from contextlib import contextmanager

@contextmanager
def db_connection(dsn: str):
    conn = connect(dsn)        # acquire
    try:
        yield conn             # hand control to the with-body
    finally:
        conn.close()           # guaranteed release, even on error

# Usage: connection is always closed
with db_connection("postgres://...") as conn:
    conn.execute("INSERT INTO events VALUES (...)")

# EAFP - idiomatic, race-free
def get_region_eafp(row: dict) -> str:
    try:
        return row["region"]
    except KeyError:
        return "unknown"

# LBYL - check first
def get_region_lbyl(row: dict) -> str:
    if "region" in row:
        return row["region"]
    return "unknown"

